export const bedaNames=['ಕಣ್ಣುಮುಚ್ಚಾಲೆ','ರತ್ತೊ ರತ್ತೊ','ಚೀಟಿ ಆಟ','ಆಣಿಕಲ್ಲು ಆಟ','ಚಾಕಬಾರ ಅಥವಾ ಕಟ್ಟಿಮನೆ ಆಟ','ಕಳ್ಳ ಪೋಲೀಸ್‌','ಉಪ್ಪೇರುಪ್ಪ ಆಟ','ಹುಣಸೇಬೀಜದ ಆಟ','ನೆನಪಿನ ಆಟ','ಬಗಟೇ ಬಗರಿ ಆಟ','ಚಾವ ಆಟ (ಏಳುಮನೆ, ಕಟ್ಟೆಮನೆ)','ಹುಲಿಮನೆ ಆಟ','ಹಾವಿನ ಪಟ್ಟದ ಆಟ','ನಾಣ್ಯದ ಆಟ','ಬಲಪ್ರಯೋಗ ಆಟ','ಕೆರೆದಡ ಆಟ','ಮರಕೋತಿ ಆಟ','ಗಜ್ಜುಗದ ಆಟ','ದೋಣಿಯ ಆಟ','ರಥದ ಆಟ','ಗೋಣಿಚೀಲ ಆಟ','ಗಣಪತಿ ಆಟ','ಉಯ್ಯಾಲೆ ಆಟ','ಕಬ್ಬಡಿ ಆಟ','ಖೋ ಖೋ ಆಟ','ಚಿನ್ನಿದಾಂಡು ಅಥವಾ ಚಿಣ್ಣಿಕೋಲು ಆಟ','ಲಗೋರಿ ಆಟ','ತುಪ್ಪ ಕಾಯಿಸುವ ಆಟ','ತೊಟ್ಟಿಲು ಆಟ','ಟೊಂಕೆ ಆಟ','ಕಪ್ಪೆ ಆಟ','ಕವಡೆ ಆಟ','ಚೇಟಿ ಕಿತುವ ಆಟ','ಚನೆ ಮನೆ ಆಟ','ನಾಟ್ಕದ ಆಟ']
