export const bookFacts=[
  {kind:'history',tab:'games',title:{en:'A sword duel before the Delhi emperor, in a Kannada poem',kn:'ಕನ್ನಡ ಕಾವ್ಯದಲ್ಲಿ ದೆಹಲಿ ಬಾದಷಹನ ಮುಂದೆ ಖಡ್ಗಯುದ್ಧ'},note:{en:'Lingannakavi’s Keladi Nripa Vijaya (third ashvasa) tells how Sankanna Nayaka of Keladi, near Delhi, saw a sword hung at the palace gate with a challenge to anyone who could face the vizier Ankushakhan, unfastened it and killed the vizier in a duel before the emperor. Srikantayya takes it as a sign that famed dagger-fighters toured the country challenging rivals, and that courts kept a street of such fighters. This is a poet’s court account, not a checked event.',kn:'ಲಿಂಗಣ್ಣ ಕವಿಯ ಕೆಳದಿ ನೃಪ ವಿಜಯದ ಮೂರನೇ ಆಶ್ವಾಸದಲ್ಲಿ ಕೆಳದಿಯ ಸಂಕಣ್ಣ ನಾಯಕ ದೆಹಲಿಯ ಬಳಿ ಅರಮನೆಯ ಬಾಗಿಲಿಗೆ ಕಟ್ಟಿದ ಖಡ್ಗವನ್ನು ಬಿಚ್ಚಿ, ದೆಹಲಿ ಬಾದಷಹನ ಮುಂದೆ ವಜೀರ ಅಂಕುಶಖಾನನೊಂದಿಗೆ ಖಡ್ಗಯುದ್ಧ ಮಾಡಿ ಕೊಂದ ಕಥೆಯಿದೆ.'},src:'Srikantayya 1989, chapter 15 (pp. 35–37)'},
  {kind:'culture',tab:'games',title:{en:'What the garadi study covers, chapter by chapter',kn:'ಗರಡಿ ಅಧ್ಯಯನದ ಅಧ್ಯಾಯಗಳು'},note:{en:'Hosapete taluk garadis: word origin and history (ch. 2), rites, beliefs and taboos (3), the art and family lines, including the role of lower castes (4), the akhada, its clay and the bout (5), wrestling holds and counters (6), training equipment and exercise (7), the wrestler’s diet, dress and community ties (8), society and garadis (9), and garadis in the modern world (10), with a table of 16 named holds in Sanskrit, Urdu and Kannada. Chapters 3, 4, 6, 7, 9 and 10 are not yet read.',kn:'ಹೊಸಪೇಟೆ ತಾಲೂಕಿನ ಗರಡಿಗಳು: ಪದ ನಿಷ್ಪತ್ತಿ, ಇತಿಹಾಸ, ಆಚರಣೆ-ನಂಬಿಕೆ-ನಿಷೇಧ, ಗರಡಿಕಲೆ ಮತ್ತು ವಂಶಪಾರಂಪರ್ಯ, ಅಖಾಡ, ಕುಸ್ತಿ ಪಟ್ಟುಗಳು, ಸಲಕರಣೆ, ಕುಸ್ತಿಪಟುವಿನ ಆಹಾರ-ವೇಷ, ಸಮಾಜ-ಸಂಸ್ಕೃತಿ, ಆಧುನಿಕ ಜಗತ್ತು.'},src:'Mallikarjun 2004, contents and introduction'},

  {kind:'people',tab:'festivals',title:{en:'Tumblers and rope-walkers: dombara-aata',kn:'ಡೊಂಬರಾಟ'},note:{en:'Poet Annaji describes dombara-aata acrobats with stilts and ropes, and Srikantayya notes that the travellers Abdur Razzaq and Linschoten also wrote about the tumblers and jugglers of the Kannada country.',kn:'ಕವಿ ಅಣ್ಣಾಜಿ ಕೋಲು, ಹಗ್ಗದ ಮೇಲಿನ ಡೊಂಬರಾಟವನ್ನು ವರ್ಣಿಸಿದ್ದಾನೆ; ಪ್ರವಾಸಿಗರಾದ ಅಬ್ದುರ್ ರಜಾಕ್ ಮತ್ತು ಲಿನ್‌ಷಾಟನ್ ಡೊಂಬರು, ಗಾರುಡಿಗರ ಬಗ್ಗೆ ಬರೆದಿದ್ದಾರೆ.'},src:'Srikantayya 1989, chapter 13 (pp. 26–27)'},

  {kind:'culture',tab:'festivals',title:{en:'Kara Hunnime: the bulls’ festival at Bairapura',kn:'ಕಾರ ಹುಣ್ಣಿಮೆ: ಎತ್ತುಗಳ ಹಬ್ಬ'},note:{en:'A 2007 study of Bairapura, Molakalmuru taluk, Chitradurga district, describes Kara Hunnime as the oxen’s festival: the animals are not used at the plough that day, are washed, their horns painted, and bells and flowers put on, and they are let run to a rock marker. The first ox is paraded and given a prize, and the running is called “karisariyuvudu”. The study adds that villagers also play lemon-throwing, coconut-breaking and kabaddi.',kn:'ಮೊಳಕಾಲ್ಮುರು ತಾಲೂಕಿನ ಬೈರಾಪುರದ ೨೦೦೭ರ ಅಧ್ಯಯನ: ಕಾರಹುಣ್ಣಿಮೆ ಎತ್ತುಗಳ ಹಬ್ಬ; ಎತ್ತುಗಳನ್ನು ತೊಳೆದು, ಕೊಂಬಿಗೆ ಬಣ್ಣ ಹಚ್ಚಿ, ಗಂಟೆ ಹೂವು ಹಾಕಿ ಓಡಿಸುತ್ತಾರೆ; ಮೊದಲು ಬಂದ ಎತ್ತಿಗೆ ಬಹುಮಾನ (ಕರಿ ಸರಿಯುವುದು); ನಿಂಬೆ ಎಸೆಯುವುದು, ತೆಂಗಿನಕಾಯಿ ಹೊಡೆಯುವುದು, ಕಬ್ಬಡ್ಡಿ ಆಟಗಳೂ ಇರುತ್ತವೆ.'},src:'Meghanatha A. K. N., ಬೈರಾಪುರದ ಮರಿಸ್ವಾಮಿ ಜಾನಪದ ಅಧ್ಯಯನ (Kannada University, Hampi, 2007; archive.org kuh.mphil.548.130184), p. 73'},
  {kind:'culture',tab:'festivals',title:{en:'Sannata and doddata: two folk-theatre kinds',kn:'ಸಣ್ಣಾಟ ಮತ್ತು ದೊಡ್ಡಾಟ'},note:{en:'A 2018 study of Sannata texts says sannata differs from doddata: doddata plots turn on battle and marriage, while sannata tells of devotees, saints and liberation and also has social plays. It names Krishna Parijata and Sangya Balya as the famous ones, with Basavanta Balavanta and Kadlimatti Kashibai among the social plays.',kn:'ದೊಡ್ಡಾಟದ ಕಥೆ ಕಾಳಗ-ಕಲ್ಯಾಣ ಕೇಂದ್ರಿತ; ಸಣ್ಣಾಟ ಶರಣರು-ಸಾಧುಸಂತರ ಜೀವನ, ಭಕ್ತಿ-ಮುಕ್ತಿಯನ್ನು ಹೇಳುತ್ತದೆ; ಕೃಷ್ಣ ಪಾರಿಜಾತ, ಸಂಗ್ಯಾಬಾಳ್ಯಾ ಪ್ರಸಿದ್ಧ; ಬಸವಂತ ಬಲವಂತ, ಕಡ್ಲಿಮಟ್ಟಿ ಕಾಶಿಬಾಯಿ ಸಾಮಾಜಿಕ ಸಣ್ಣಾಟಗಳು.'},src:'S. P. Madrekar, ಸಣ್ಣಾಟ ಪಠ್ಯಗಳ ಸಾಂಸ್ಕೃತಿಕ ಅಧ್ಯಯನ (Kannada University, Hampi, 2018; archive.org kuh.913.mud.138316), introduction'},
  {kind:'culture',tab:'festivals',title:{en:'Yakshagana make-up and costume of the coast',kn:'ಕರಾವಳಿಯ ಯಕ್ಷಗಾನ ಮುಖವರ್ಣಿಕೆ ಮತ್ತು ವೇಷಭೂಷಣ'},note:{en:'A 2007 art-history thesis argues that coastal Yakshagana’s face painting, jewellery and costume were shaped by the coastal environment, history and religion. Its chapters cover the cultural background, the design of face painting (which borrows from nature and animals) and the cloth designs used for different characters.',kn:'ಕರಾವಳಿಯ ಯಕ್ಷಗಾನದ ಮುಖವರ್ಣಿಕೆ, ಆಭರಣ, ವೇಷಭೂಷಣಗಳು ಅಲ್ಲಿನ ಪರಿಸರ, ಇತಿಹಾಸ, ಧರ್ಮದ ಪ್ರಭಾವದಿಂದ ರೂಪುಗೊಂಡವು ಎಂದು ವಾದಿಸುತ್ತದೆ.'},src:'Vishwanatha A. S., ಕರಾವಳಿ ಕರ್ನಾಟಕದ ಯಕ್ಷಗಾನ ದೃಶ್ಯಕಲೆಯ ಮುಖವರ್ಣಿಕೆ ಮತ್ತು ವೇಷಭೂಷಣ (Kannada University, Hampi, 2007; archive.org kuh.214.049108), chapters 2 and 3'},
  {kind:'heritage',tab:'festivals',title:{en:'Folk sculpture studies, north and south',kn:'ಜನಪದ ಶಿಲ್ಪಕಲೆ ಅಧ್ಯಯನಗಳು'},note:{en:'Two Kannada University theses survey folk sculpture across materials such as stone, clay, wood and metal, including memorial stones and sati stones: Shivananda Bantanura’s on north Karnataka (2002) and B. Lakshmipati’s on south Karnataka (2009, eight chapters on the range, classification and uses of folk sculpture). Only their chapter outlines were read.',kn:'ಉತ್ತರ ಕರ್ನಾಟಕದ (ಶಿವಾನಂದ ಬಂಟನೂರ, ೨೦೦೨) ಮತ್ತು ದಕ್ಷಿಣ ಕರ್ನಾಟಕದ (ಬಿ. ಲಕ್ಷ್ಮೀಪತಿ, ೨೦೦೯) ಜನಪದ ಶಿಲ್ಪಕಲೆಯನ್ನು ಕಲ್ಲು, ಮಣ್ಣು, ಮರ, ಲೋಹ ಮಾಧ್ಯಮಗಳಲ್ಲಿ ಅಧ್ಯಯನ ಮಾಡಲಾಗಿದೆ.'},src:'archive.org kuh.62.ban.049721 and kuh.283.lak.049176 (chapter outlines)'},

  {kind:'history',tab:'festivals',title:{en:'Navaratri in the poems, from Vijayanagara to Mysuru',kn:'ಕಾವ್ಯಗಳಲ್ಲಿ ನವರಾತ್ರಿ: ವಿಜಯನಗರದಿಂದ ಮೈಸೂರಿಗೆ'},note:{en:'Ratnakara’s Bharatesha Vaibhava gives a whole section, the “Navaratri Sandhi”, to the court festival, with puppetry, dombara-aata, indrajala, wrestling, elephant and horse displays and fireworks, and Srikantayya says it matches the travellers Abdur Razzaq, Paes and Nuniz. Govinda Vaidya’s Kanteerava Narasaraja Vijaya describes the Mahanavami court and the Vijayadashami Jamboo Savari of the Wodeyars, and he sees Ratnakara’s influence on it. One passage shows a rider splitting a lime from a galloping horse with arrows.',kn:'ರತ್ನಾಕರನ ಭರತೇಶ ವೈಭವದ “ನವರಾತ್ರಿ ಸಂಧಿ” ವಿಜಯನಗರದ ಉತ್ಸವವನ್ನು ವರ್ಣಿಸುತ್ತದೆ; ಬೊಂಬೆಯಾಟ, ಡೊಂಬರಾಟ, ಇಂದ್ರಜಾಲ, ಮಲ್ಲಯುದ್ಧ, ಆನೆ-ಕುದುರೆ ವಿನೋದ, ಬಾಣಬಿರುಸು ಇದರಲ್ಲಿವೆ. ಗೋವಿಂದ ವೈದ್ಯನ ಕಂಠೀರವ ನರಸರಾಜ ವಿಜಯ ಮಹಾನವಮಿ ದರ್ಬಾರ್ ಮತ್ತು ವಿಜಯದಶಮಿಯ ಜಂಬೂಸವಾರಿಯನ್ನು ವರ್ಣಿಸುತ್ತದೆ.'},src:'Srikantayya 1989, chapters 10 to 12 (pp. 21–26)'},

  {kind:'culture',tab:'games',title:{en:'The childhood games Kumaravyasa names',kn:'ಕುಮಾರವ್ಯಾಸ ಹೇಳುವ ಬಾಲ್ಯದ ಆಟಗಳು'},note:{en:'In the Adi Parva of the Gadugina Bharata, Kumaravyasa lists about 18 games of the young Kauravas and Pandavas, thought to reflect the children’s play of his own day: alinerike (a piggyback game), hidigavade (a game with cowries in the hand), chinnikolu, gudugu (shouting “gandu gudu”, perhaps like kabaddi), guttina chendu and a hide-and-seek with a ball, kambadagadane (pole tag), kannamuchale, a hopscotch with a tile piece (hallae aata), kolumara aata (a tree-monkey game), chettumuri aata and others whose meaning is no longer known.',kn:'ಗದುಗಿನ ಭಾರತದ ಆದಿಪರ್ವದಲ್ಲಿ ಕುಮಾರವ್ಯಾಸ ಸುಮಾರು ೧೮ ಆಟಗಳನ್ನು ಹೆಸರಿಸಿದ್ದಾನೆ: ಆಳಿನೇರಿಕೆ, ಹಿಡಿಗವಡೆ, ಚಿಣಿಕೋಲು, ಗುಡುಗು (ಕಬಡ್ಡಿಯಂತೆ ಇರಬಹುದು), ಗುತ್ತಿನ ಚೆಂಡು, ಕಂಬದಗಡಣೆ, ಕಣ್ಣುಮುಚ್ಚಾಲೆ, ಹಲ್ಲೆಯಾಟ, ಕೋಲುಮರನಾಟ (ಮರಕೋತಿ), ಚೆಟ್ಟುಮುರಿಯಾಟ ಮುಂತಾದವು.'},src:'Srikantayya 1989, chapter 6 (pp. 14–15)'},
  {kind:'history',tab:'games',title:{en:'Gambling in Vijayanagara, as Kanakadasa saw it',kn:'ಕನಕದಾಸರು ಕಂಡ ವಿಜಯನಗರದ ಜೂಜು'},note:{en:'Kanakadasa’s Mohanatarangini describes gambling on bananas, coconuts and sugarcane, and gamblers playing pagade, rayabogari, solleha and oppi in every house; Kumaravyasa’s assemblies include gamblers among the entertainers. Poets also warn against it as one of the seven vices.',kn:'ಕನಕದಾಸರ ಮೋಹನತರಂಗಿಣಿಯಲ್ಲಿ ಬಾಳೆಹಣ್ಣು, ತೆಂಗಿನಕಾಯಿ, ಕಬ್ಬಿನ ಜೂಜು, ಪಗಡೆ, ರಾಯಬೊಗರಿ, ಸೊಲ್ಲೆಹ ಮುಂತಾದ ಜೂಜಿನಾಟಗಳ ವರ್ಣನೆಯಿದೆ; ಸಪ್ತವ್ಯಸನಗಳಲ್ಲಿ ಜೂಜು ಒಂದು ಎಂದು ಕವಿಗಳು ಎಚ್ಚರಿಸಿದ್ದಾರೆ.'},src:'Srikantayya 1989, chapter 5 (pp. 12–14)'},

  {kind:'history',tab:'games',title:{en:'Sixty game names in forty to fifty Kannada works',kn:'೪೦–೫೦ ಕನ್ನಡ ಕೃತಿಗಳಲ್ಲಿ ಅರವತ್ತು ಆಟಗಳ ಹೆಸರು'},note:{en:'K. Srikantayya (1989) read 40 to 50 Kannada works and found about sixty game names, most still known, but some, such as aalinerike, chendina hoonate, kambadagadane and harihalage, with no known meaning (Kittel’s dictionary is silent). His examples of vivid scenes: Kanakadasa’s Mohanatarangini (gambling), Nanjunda’s Ramanathacharite (a royal ball game and animal fights), Govinda Vaidya’s Kanteerava Narasaraja Vijaya (animal fights, fire shows), Lingannakavi’s Keladinripavijaya (a sword duel), Ratnakara’s Bharatesha Vaibhava (fire shows, jugglery), Annaji (dombara-aata), Purandara Dasa (gajjuga), Kumaravyasa (wrestling), and hunting scenes in Raghavanka, Kumaravyasa, Salva and Nagaraja.',kn:'ಡಾ. ಕೆ. ಶ್ರೀಕಂಠಯ್ಯ (೧೯೮೯) ೪೦–೫೦ ಕನ್ನಡ ಕೃತಿಗಳಲ್ಲಿ ಸುಮಾರು ಅರವತ್ತು ಆಟಗಳ ಹೆಸರುಗಳನ್ನು ಕಂಡರು; ಕೆಲವಕ್ಕೆ ಅರ್ಥ ಇಂದು ತಿಳಿಯದು. ಕನಕದಾಸ, ನಂಜುಂಡ, ಗೋವಿಂದ ವೈದ್ಯ, ಲಿಂಗಣ್ಣ ಕವಿ, ರತ್ನಾಕರ, ಪುರಂದರದಾಸ, ಕುಮಾರವ್ಯಾಸ ಮೊದಲಾದ ಕವಿಗಳ ವರ್ಣನೆಗಳನ್ನು ಉಲ್ಲೇಖಿಸುತ್ತಾರೆ.'},src:'Srikantayya 1989, introduction (pp. 1–4); archive.org crmn.kannadakavigaluk0000drks'},

  {kind:'culture',tab:'festivals',title:{en:'How togalu gombeyaata is made and shown',kn:'ತೊಗಲು ಗೊಂಬೆಯಾಟ ಹೇಗೆ'},note:{en:'A 1995 Karnataka Lalitakala Academy booklet on folk painting says the figures are cut and coloured in the skins of goat, sheep, buffalo, donkey or camel, and shown at night behind a lit screen with musicians, telling stories. It treats the art as purely of folk origin.',kn:'ಮೇಕೆ, ಕುರಿ, ಎಮ್ಮೆ, ಕತ್ತೆ, ಒಂಟೆ ಚರ್ಮದಲ್ಲಿ ಚಿತ್ರ ಕೊರೆದು ಬಣ್ಣ ಹಚ್ಚಿ, ರಾತ್ರಿ ದೀಪದ ಬೆಳಕಿನಲ್ಲಿ ವಾದ್ಯಮೇಳದೊಂದಿಗೆ ಕಥೆ ಆಡಿಸುವುದು ತೊಗಲುಗೊಂಬೆಯಾಟ.'},src:'S. C. Patil, ಜನಪದ ಚಿತ್ರಕಲೆ (Karnataka Lalitakala Academy, 1995; archive.org kla.janapadachitraka0000drsc), section on togalugombe'},

  {kind:'culture',tab:'festivals',title:{en:'The Killekyatha leather-puppet showmen',kn:'ಕಿಳ್ಳೇಕ್ಯಾತರು: ತೊಗಲು ಗೊಂಬೆಯಾಟದವರು'},note:{en:'A 1977 Anthropological Survey of India study describes the Killekyatha (also Katabu, Gombe Rama) as a Marathi-speaking nomadic group known as togalu gombe aata performers, whose leather-picture shows were once very popular in villages and are declining before cinema and drama. Their shows use comic characters, Killekyata (or Sillekyata) and his wife Bangarakka. The gazetteers counted 445 in Dharwad (1884) and 376 in Bijapur (1888), most in Badami taluk, where the author lived in a village 18 miles from Badami.',kn:'ಕಿಳ್ಳೇಕ್ಯಾತರು (ಕಟಬು, ಗೊಂಬೆ ರಾಮ ಎಂದೂ) ಮರಾಠಿ ಮಾತನಾಡುವ ಅಲೆಮಾರಿ ಸಮುದಾಯ; ತೊಗಲು ಗೊಂಬೆಯಾಟ ಪ್ರದರ್ಶಿಸುತ್ತಾರೆ; ಸಿನೆಮಾ-ನಾಟಕಗಳ ಬರುವಿಕೆಯಿಂದ ಈ ಕಲೆ ಕ್ಷೀಣಿಸುತ್ತಿದೆ; ಹಾಸ್ಯ ಪಾತ್ರಗಳು ಕಿಳ್ಳೇಕ್ಯಾತ ಮತ್ತು ಬಂಗಾರಕ್ಕ.'},src:'S. G. Morab, The Killekyatha: a nomadic folk-artist community of northern Mysore (Anthropological Survey of India, 1977; archive.org tribal.killekyathanomad0000sgmo), early chapters'},
  {kind:'culture',tab:'festivals',title:{en:'Kambala is a ritual as well as a race',kn:'ಕಂಬುಲ: ಆಟ ಮತ್ತು ಆಚರಣೆ'},note:{en:'Bilimale argues from field description that coastal kambula includes the Koraga dance, planting a flower-decked pole with milk offered, snake worship and next-day paddy planting, so it cannot be read only as sport.',kn:'ಬಿಳಿಮಲೆಯವರು ಕಂಬುಲವನ್ನು ಕೇವಲ ಕ್ರೀಡೆಯಾಗಿ ಓದಲಾಗದು ಎಂದು ವಾದಿಸುತ್ತಾರೆ.'},src:'Bilimale 1990, “Kambula: game or ritual?”'},

  {kind:'heritage',tab:'festivals',title:{en:'What a garadi looks like',kn:'ಗರಡಿ ಮನೆ ಹೇಗಿರುತ್ತದೆ'},note:{en:'The Hosapete study describes small garadi-manes with an earthen arena (akhada) strewn with about two feet of red clay (mattimannu), in one case fetched from below a hill at Hanumanahalli; a niche in the wall holds a Hanuman picture or image; and training is with stone weights. Arenas are measured in feet (for example 18 by 14 ft).',kn:'ಹೊಸಪೇಟೆ ಅಧ್ಯಯನದ ಪ್ರಕಾರ ಗರಡಿ ಮನೆಯ ಅಖಾಡದಲ್ಲಿ ಸುಮಾರು ಎರಡು ಅಡಿ ಮಟ್ಟಿಮಣ್ಣು ಹಾಕಿರುತ್ತಾರೆ; ಗೋಡೆಯ ಗೂಡಿನಲ್ಲಿ ಹನುಮಂತನ ಚಿತ್ರ; ಕಲ್ಲಿನ ಗುಂಡುಗಳ ಸಾಧನೆ.'},src:'Mallikarjun 2004, ch. 2 field descriptions (pp. 29 and nearby)'},
  {kind:'history',tab:'festivals',title:{en:'Hanuman temples and garadis together',kn:'ಹನುಮನ ಗುಡಿ ಮತ್ತು ಗರಡಿ'},note:{en:'The study repeats a report that the saint Samartha Ramdas built about 1,200 Hanuman temples and as many garadi-manes, joining bodily strength to devotion.',kn:'ಸಮರ್ಥ ರಾಮದಾಸರು ಸುಮಾರು ೧೨೦೦ ಹನುಮಂತನ ಗುಡಿಗಳನ್ನು ಮತ್ತು ಅಷ್ಟೇ ಗರಡಿಮನೆಗಳನ್ನು ಕಟ್ಟಿಸಿದರು ಎಂಬ ಉಲ್ಲೇಖವನ್ನು ಅಧ್ಯಯನ ನೀಡುತ್ತದೆ.'},src:'Mallikarjun 2004, ch. 2.3 (p. 23)'},

  {kind:'culture',tab:'games',title:{en:'What children and adults were called for crossing game lines',kn:'ಆಟದ ಗೆರೆ ದಾಟಿದರೆ ಬರುತ್ತಿದ್ದ ಹೆಸರು'},note:{en:'A study of Gangamatha folklore in Mandya district sorts games into children’s, men’s and women’s games. A girl who joins a boys’ game is called “gandubeeri” and a boy who joins a girls’ game “hennaiga”: a rule worth asking about in every village.',kn:'ಮಂಡ್ಯ ಜಿಲ್ಲೆಯ ಗಂಗಾಮತಸ್ಥರ ಅಧ್ಯಯನ ಆಟಗಳನ್ನು ಮಕ್ಕಳ, ಗಂಡಸರ, ಹೆಂಗಸರ ಆಟ ಎಂದು ವಿಂಗಡಿಸಿದೆ; ಹುಡುಗಿ ಹುಡುಗರ ಆಟದಲ್ಲಿ ಸೇರಿದರೆ “ಗಂಡು ಬೀರಿ”, ಹುಡುಗ ಹುಡುಗಿಯರ ಆಟದಲ್ಲಿ ಸೇರಿದರೆ “ಹೆಣ್ಣಿಗ”.'},src:'K. Krishnegowda (Gangamatha folklore, Mandya, 2010), §3.11, p. 176'},
  {kind:'culture',tab:'games',title:{en:'Local names of village games: Soraturu, Gadag district',kn:'ಸೊರಟೂರ (ಗದಗ ಜಿಲ್ಲೆ) ಆಟಗಳ ಸ್ಥಳೀಯ ಹೆಸರು'},note:{en:'A 2024 thesis on the village of Soraturu, near the Kappatagudda hills, has a section on its folk sports (§7.3, p. 183). It records a glass-marble game called gundadaaba with its own words for hand positions, a tree-chasing game also called “hottippa aata”, and a spinning-top game with a type called “ginni”.',kn:'ಕಪ್ಪತ್ತಗುಡ್ಡದ ಬಳಿಯ ಸೊರಟೂರ ಗ್ರಾಮದ ೨೦೨೪ರ ಅಧ್ಯಯನ ಜನಪದ ಕ್ರೀಡೆಗಳನ್ನು ದಾಖಲಿಸಿದೆ: ಗುಂಡಾದಾಬ (ಗಾಜಿನ ಗುಂಡು), “ಹೊಟ್ಟಿಪ್ಪ ಆಟ” (ಮರಕೋತಿ), ಬಗರಿಯ “ಗಿನ್ನಿ” ಪ್ರಕಾರ.'},src:'Madannavar 2024, §7.3'},
  {kind:'culture',tab:'games',title:{en:'Over 32 living games in Bidar taluk',kn:'ಬೀದರ ತಾಲೂಕಿನಲ್ಲಿ ೩೨ಕ್ಕೂ ಹೆಚ್ಚು ದೇಶಿ ಕ್ರೀಡೆಗಳು'},note:{en:'A 2018 study of Bidar taluk devotes chapter 5 (pp. 94–145) to indigenous games and says more than 32 are still alive there, with thousands of years of cultural history behind them.',kn:'೨೦೧೮ರ ಬೀದರ ತಾಲೂಕು ಅಧ್ಯಯನದ ಐದನೇ ಅಧ್ಯಾಯ (ಪು. ೯೪–೧೪೫) ೩೨ಕ್ಕೂ ಹೆಚ್ಚು ದೇಶಿ ಕ್ರೀಡೆಗಳು ಜೀವಂತವಾಗಿವೆ ಎನ್ನುತ್ತದೆ.'},src:'Sure 2018, ch. 5'},
  {kind:'history',tab:'games',title:{en:'Yalandur: games of the past',kn:'ಯಳಂದೂರಿನ ಹಿಂದಿನ ಆಟಗಳು'},note:{en:'A 2009 study of Yalandur (Chamarajanagar district) lists chinnikolaata, lagge chendaata, kabaddi, marakothi and kaddi aata as games of the past, played less now.',kn:'ಯಳಂದೂರಿನ ೨೦೦೯ರ ಅಧ್ಯಯನ ಚಿಣ್ಣಿಕೋಲಾಟ, ಲಗ್ಗೆ ಚೆಂಡಾಟ, ಕಬ್ಬಡ್ಡಿ, ಮರಕೋತಿ, ಕಡ್ಡಿ ಆಟಗಳನ್ನು ಹಿಂದಿನ ಆಟಗಳೆಂದು ಹೆಸರಿಸಿದೆ.'},src:'H. S. Padma 2009, “Yalandurina kreedegalu”, p. 66'},
  {kind:'heritage',tab:'festivals',title:{en:'Carved scenes of sport at Hampi',kn:'ಹಂಪಿಯ ಉಬ್ಬು ಶಿಲ್ಪಗಳಲ್ಲಿ ಕ್ರೀಡೆ'},note:{en:'The Vijayanagara study says reliefs at the Hazara Rama, Balakrishna and Vijaya Vitthala temples show dance, stick play, sword play, wrestling and music, and that a hunting festival is shown on the Mahanavami platform.',kn:'ಹಜಾರರಾಮ, ಬಾಲಕೃಷ್ಣ, ವಿಜಯ ವಿಠಲ ದೇವಾಲಯಗಳ ಶಿಲ್ಪಗಳಲ್ಲಿ ಕೋಲಾಟ, ಕತ್ತಿವರಸೆ, ಕುಸ್ತಿ, ನೃತ್ಯ, ವಾದ್ಯ ಚಿತ್ರಿತವಾಗಿವೆ (ಪು. ೧೦).'},src:'Manjanna 2016, p. 10 and pp. 187–188'},
  {kind:'culture',tab:'festivals',title:{en:'Festivals named for Vijayanagara',kn:'ವಿಜಯನಗರದ ಹಬ್ಬಗಳು'},note:{en:'Besides Mahanavami, the study names Ramanavami, Krishna Janmashtami, Deepavali, Mahashivaratri, Kamana habba, Badige habba and the hunting festival as occasions for wrestling, puppet shows, processions and dance (p. 16).',kn:'ಮಹಾನವಮಿ, ರಾಮನವಮಿ, ಕೃಷ್ಣಜನ್ಮಾಷ್ಟಮಿ, ದೀಪಾವಳಿ, ಮಹಾಶಿವರಾತ್ರಿ, ಕಾಮನ ಹಬ್ಬ, ಬಡಿಗೆ ಹಬ್ಬ, ಬೇಟೆ ಹಬ್ಬಗಳಲ್ಲಿ ಮಲ್ಲಯುದ್ಧ, ಗೊಂಬೆಯಾಟ, ಮೆರವಣಿಗೆ (ಪು. ೧೬).'},src:'Manjanna 2016, p. 16'},
  {kind:'history',tab:'festivals',title:{en:'Animal contests as royal entertainment',kn:'ಪ್ರಾಣಿ ಕಾಳಗ ವಿನೋದ'},note:{en:'The study says rams, elephants, bulls and cocks were trained for matches at Vijayanagara, and that Paes described a courtyard as large as a fighting arena (pp. 105, 115).',kn:'ವಿಜಯನಗರದಲ್ಲಿ ಟಗರು, ಆನೆ, ಗೂಳಿ, ಕೋಳಿಗಳಿಗೆ ತರಬೇತಿ ನೀಡಿ ಪಂದ್ಯ ಏರ್ಪಡಿಸುತ್ತಿದ್ದರು (ಪು. ೧೦೫).'},src:'Manjanna 2016, pp. 105, 115'},

  {kind:'people',tab:'games',title:{en:'Mummadi Krishnaraja Wodeyar (1794–1868)',kn:'ಮುಮ್ಮಡಿ ಕೃಷ್ಣರಾಜ ಒಡೆಯರ್ (೧೭೯೪–೧೮೬೮)'},note:{en:'Born at Srirangapatna. He played Ganjifa, which is why the art flourished under him; the booklet says the Mysore style of miniature painting took shape in his time, and that he devised ten well-known games of his own.',kn:'ಶ್ರೀರಂಗಪಟ್ಟಣದಲ್ಲಿ ಜನಿಸಿದರು. ಗಂಜೀಫಾ ಆಡುತ್ತಿದ್ದರು; ಅವರ ಕಾಲದಲ್ಲಿ ಮೈಸೂರು ಚಿಕಣಿ ಚಿತ್ರ ಶೈಲಿ ರೂಪುಗೊಂಡಿತು ಎನ್ನುತ್ತದೆ ಕಿರುಹೊತ್ತಿಗೆ.'},src:'Shivashankara 1996, Foreword and main text'},
  {kind:'people',tab:'games',title:{en:'Raghupathi Bhat of Nagamangala',kn:'ನಾಗಮಂಗಲದ ರಘುಪತಿ ಭಟ್ಟ'},note:{en:'Revived the Ganjifa craft; known as “Ganjifa Raghupati”. He supplied the colour photographs and rare cards for the booklet.',kn:'ಗಂಜೀಫಾ ಕಲೆಯನ್ನು ಪುನರುಜ್ಜೀವನಗೊಳಿಸಿದರು; “ಗಂಜೀಫಾ ರಘುಪತಿ” ಎಂದು ಹೆಸರಾಗಿದ್ದಾರೆ.'},src:'Shivashankara 1996, main text'},
  {kind:'heritage',tab:'games',title:{en:'Where Ganjifa cards are kept',kn:'ಗಂಜೀಫಾ ಎಲೆಗಳು ಎಲ್ಲಿವೆ'},note:{en:'Srirangapatna Ganjifa gallery; the art gallery in Jaganmohana Palace, Mysuru; the folklore museum of the University of Mysore; the Manjusha museum, Dharmasthala (191 cards of an old Sawantwadi Dashavatara set donated by Manjeshwar Dinakara Rao); the government museum, Shivamogga.',kn:'ಶ್ರೀರಂಗಪಟ್ಟಣದ ಗಂಜೀಫಾ ಗ್ಯಾಲರಿ; ಮೈಸೂರಿನ ಜಗನ್ಮೋಹನ ಅರಮನೆ; ಮೈಸೂರು ವಿಶ್ವವಿದ್ಯಾನಿಲಯದ ಜಾನಪದ ವಸ್ತು ಸಂಗ್ರಹಾಲಯ; ಧರ್ಮಸ್ಥಳದ ಮಂಜೂಷಾ ವಸ್ತು ಸಂಗ್ರಹಾಲಯ; ಶಿವಮೊಗ್ಗ ಸರ್ಕಾರಿ ವಸ್ತು ಸಂಗ್ರಹಾಲಯ.'},src:'Shivashankara 1996, preface and main text'},
  {kind:'culture',tab:'games',title:{en:'Ganjifa towns in Karnataka',kn:'ಕರ್ನಾಟಕದ ಗಂಜೀಫಾ ಊರುಗಳು'},note:{en:'The booklet lists Mysuru, Bengaluru, Srirangapatna, Ganjam, Nagamangala, Kinnala, Surapura, Dharwad and Belagavi among the places where Ganjifa is found, and names natural colours (for example chinnada banna, ingleeka, pista, sampige) used on the cards.',kn:'ಮೈಸೂರು, ಬೆಂಗಳೂರು, ಶ್ರೀರಂಗಪಟ್ಟಣ, ಗಂಜಾಂ, ನಾಗಮಂಗಲ, ಕಿನ್ನಾಳ, ಸುರಪುರ, ಧಾರವಾಡ, ಬೆಳಗಾವಿ ಊರುಗಳಲ್ಲಿ ಗಂಜೀಫಾ ಕಾಣಸಿಗುತ್ತದೆ ಎಂದು ಕಿರುಹೊತ್ತಿಗೆ ಪಟ್ಟಿಮಾಡಿದೆ.'},src:'Shivashankara 1996, main text'},
  {kind:'history',tab:'festivals',title:{en:'A visitor’s account of the royal dance school',kn:'ಅರಮನೆಯ ನೃತ್ಯ ಶಾಲೆ'},note:{en:'The Vijayanagara study cites the traveller Domingo Paes for a dance school inside the palace for the women of the royal household, and says relief sculptures on monuments show sport, dance, music and hunting.',kn:'ಅರಮನೆಯ ಸ್ತ್ರೀಯರಿಗಾಗಿ ನರ್ತನ ಶಾಲೆ ಇತ್ತು ಎಂದು ಪ್ರವಾಸಿ ಡೊಮಿಂಗೋ ಪಾಯೆಸ್ ಹೇಳಿದ್ದನ್ನು ಅಧ್ಯಯನ ಉಲ್ಲೇಖಿಸುತ್ತದೆ.'},src:'Manjanna 2016, introduction'},
  {kind:'culture',tab:'festivals',title:{en:'How the Chitradurga study was gathered',kn:'ಚಿತ್ರದುರ್ಗ ಅಧ್ಯಯನ ಹೇಗೆ ನಡೆಯಿತು'},note:{en:'It groups the district’s games into five kinds (strength, mind games, festival and tradition, animal and bird, fun contests) and ends with a questionnaire of 35 questions put to players: which games, where and when, rules, taboos, food, beliefs, links to religion, and legends. A good model for village collection.',kn:'ಜಿಲ್ಲೆಯ ಆಟಗಳನ್ನು ಐದು ಬಗೆಗಳಾಗಿ ವಿಂಗಡಿಸಿದೆ ಮತ್ತು ಆಟಗಾರರಿಗೆ ೩೫ ಪ್ರಶ್ನೆಗಳ ಪ್ರಶ್ನಾವಳಿಯನ್ನು ನೀಡಿದೆ.'},src:'Niranjanamurthy 2017, ch. 4 §3 and appendix'}
]
